from lib import *
S = SS('g20')
steps = [
    step("iter.Pull 把推式迭代器变成拉式:next, stop := iter.Pull(Count(2))。第 1、2 次 next() 分别得到 (0, true)、(1, true),每次迭代器才被推进到下一个 yield;第 3 次 next() 让迭代器自然结束并执行 defer,返回 (0, false);第 4 次仍是 (0, false);stop() 连续调用两次没问题。只取一个值就 stop():迭代器看到 yield 返回 false,走清理路径;stop 之后再 next() 得到 (0, false)。用 Pull 合并两个有序序列 {1,4,9} 与 {2,3,10,11} 得到 [1 2 3 4 9 10 11]。", t=tl(S(1)), done=lidx(S(1), '第 1 次 next()', '第 2 次 next()', '第 3 次 next()', '第 4 次 next()'), mark=lidx(S(1), '提前 stop()', 'stop 之后再 next()', '合并两个有序序列'), kv=KV([['next()', '推进迭代器到下一个 yield,返回 (值, true)'], ['取完之后', '(0, false);迭代器的 defer 在那一次执行'], ['stop() 提前结束', 'yield 返回 false,迭代器清理;可重复调用'], ['合并两个序列', 'Pull 两个迭代器,逐个比较:[1 2 3 4 9 10 11]']], ['stop() 提前结束'])),
    step("迭代器里 panic 会从 next() 的调用处抛出:迭代器 yield(1) 之后 panic(\"迭代器自己出错了\"),在调用 next() 的函数里 recover 到的就是这个值。", t=tl(S(2)), mark=lidx(S(2), 'recover 收到'), kv=KV([['迭代器里的 panic', '从 next() 的调用处抛出,可以在调用者里 recover']], ['迭代器里的 panic'])),
    step("Pull 的底层是 goroutine:创建 1000 个 Pull、各取 1 个值、都不 stop:NumGoroutine 从 1 变成 1001;全部 stop() 之后回到 1。再创建 10000 个 Pull,各取 1 个、不 stop、直接丢弃引用:GC 之后堆从 0.66 MiB 涨到 6.94 MiB,NumGoroutine = 10001——丢弃引用并不会回收它们。", t=tl(S(3)), done=lidx(S(3), '全部 stop() 之后'), mark=lidx(S(3), '创建 1000 个 Pull', '再创建 10000 个 Pull'), b=bars([['创建前 goroutine', 1, '1'], ['1000 个 Pull 未 stop', 1001, '1001'], ['全部 stop 之后', 1, '1'], ['又 10000 个未 stop', 10001, '10001']], 10001, done=[0, 2], mark=[1, 3]), kv=KV([['1000 个 Pull,不 stop', 'NumGoroutine 1 → 1001'], ['全部 stop()', '回到 1'], ['又 10000 个,丢弃引用', 'NumGoroutine = 10001;堆 0.66 → 6.94 MiB']], ['又 10000 个,丢弃引用'])),
    step("成本(1000 个 int,7 轮取中位数):for range seq 2040.39 ns/op;iter.Pull + next() 逐个取 43979.79 ns/op,约是前者的 21.6 倍(每个元素约 44 ns);创建一个 Pull、取 1 个元素并 stop 一共 207.49 ns/op。分配:SumRange 2 次,SumPull(1000 个元素)6 次。", t=tl(S(4)), done=lidx(S(4), 'for range seq'), mark=lidx(S(4), 'iter.Pull + next()', '只创建并取 1 个元素', 'AllocsPerRun'), b=bars([['for range(推)ns/op', 2040.39, '2040'], ['iter.Pull + next(拉)ns/op', 43979.79, '43980'], ['创建+1 次 next+stop ns/op', 207.49, '207']], 43979.79, done=[0, 2], mark=[1]), kv=KV([['推式 for range(1000 个)', '2040.39 ns/op'], ['拉式 Pull(1000 个)', '43979.79 ns/op,约 21.6 倍'], ['创建 + 取 1 个 + stop', '207.49 ns/op']], ['拉式 Pull(1000 个)'])),
    step("源码线索:iter/iter.go 里声明 newcoro 与 coroswitch(链接到 runtime.newcoro、runtime.coroswitch);runtime/coro.go 开头的注释说 coro 是“extra concurrency without extra parallelism”,可以想成一个总有一个 goroutine 阻塞其上的特殊 channel——调用 coroswitch 时,调用者变成被阻塞的那个 goroutine,原来阻塞的那个开始运行。", t=tl(S(5)), done=lidx(S(5), 'iter/iter.go:233', 'iter/iter.go:236'), mark=lidx(S(5), 'extra concurrency without extra parallelism', 'special channel'), kv=KV([['iter.Pull', '调用 runtime.newcoro 创建协程'], ['next / stop', '每次通过 runtime.coroswitch 在两个 goroutine 之间直接切换'], ['coro', '“extra concurrency without extra parallelism”']], ['iter.Pull'])),
]
A = mkartg('g20', 20, 'Go,迭代器,iter.Pull,协程,goroutine,真实验证,动画演示',
    '在 Go 1.27.1 里验证 iter.Pull:next 一次推进迭代器一步,取完或 stop 时迭代器的 defer 才执行,迭代器里的 panic 从 next 抛出;底层是 runtime.newcoro 创建的 goroutine,不 stop 就泄漏(1000 个 Pull 使 NumGoroutine 从 1 变成 1001,丢弃引用也不回收);1000 个元素的求和 Pull 比 for range 慢约 21.6 倍。',
    '推式迭代器(range-over-func)用起来方便,但有时需要“拉式”:一次取一个,在两个序列之间交替。iter.Pull 能把推式变成拉式,代价是什么?这篇用实验回答:语义、panic、泄漏、耗时,以及它在运行时里是怎么实现的。',
    [('1 → 1001', '创建 1000 个 Pull、各取一个、不 stop 之后的 goroutine 数'), ('21.6 倍', '1000 个元素,Pull 逐个 next 与 for range 的耗时比(43980 ns vs 2040 ns)'), ('207 ns', '创建一个 Pull、取一个元素并 stop 的耗时')],
    [('语义', '<p><code>next</code> 每调用一次,迭代器才执行到下一个 <code>yield</code>;迭代器的 <code>defer</code> 在它结束(取完或被 <code>stop</code>)时才执行。<code>stop</code> 让 <code>yield</code> 返回 <code>false</code>,迭代器走正常的提前退出路径,并且可以重复调用。合并两个有序序列是最典型的用法——两个 Pull,逐个比较。</p>'),
     ('panic', '<p>迭代器里的 panic 会传到调用 <code>next</code> 的那个 goroutine,所以可以在调用处 <code>recover</code>。这个实验只验证了最简单的一种情形,多个 Pull 嵌套时的传播细节我没有测。</p>'),
     ('goroutine 泄漏', '<p>实验显示 <code>iter.Pull</code> 每调用一次就多一个 goroutine,直到取完或 <code>stop</code>。<b>不 stop 又不取完,goroutine 会一直存在</b>:丢弃 <code>next</code>/<code>stop</code> 的引用也回收不了它(10000 个之后 NumGoroutine 还是 10001,堆里多了约 6 MiB)。所以总要 <code>defer stop()</code>。</p>'),
     ('耗时', '<p>每次 <code>next</code> 要在两个 goroutine 之间切换一次,实测每个元素约 44 ns,而 <code>for range</code> 不跨 goroutine,每个元素约 2 ns。需要“拉”的时候才用 <code>Pull</code>;能用 <code>range</code> 的地方不要为了写法换成 <code>Pull</code>。这些是 arm64 上的数字。</p>'),
     ('实现', '<p>源码里 <code>iter.Pull</code> 通过 <code>newcoro</code> 与 <code>coroswitch</code>(<code>runtime/coro.go</code>)实现。<code>coro</code> 的注释把它描述成“只有并发、没有并行”:切换时调用者与被阻塞的 goroutine 直接对调,不经过通常的调度循环。这解释了为什么它比 channel 往返快得多,但注释之外的实现细节我没有逐行读。</p>')],
    steps,
    [ENV_G + '。语义与 panic 用真实程序验证;goroutine 数来自 runtime.NumGoroutine,堆来自 runtime.ReadMemStats(先 GC);基准测试 7 轮取中位数;读过的源码:iter/iter.go 里 Pull 对 newcoro / coroswitch 的使用与 runtime/coro.go 开头的注释',
     '没有验证:Pull2 的行为(与 Pull 对称,没有单独运行)、从另一个 goroutine 调用 next 的限制、与 LockOSThread 的交互(coro.go 里有相关字段)、嵌套 Pull 的 panic 传播、与 channel 实现同样功能时的耗时对比'],
    'iter.Pull')
